# ARKAVATHI OVERVIEW + INTRODUCTION CLIENT CHANGES PATCH
# Frontend-only patch. No backend files, APIs, DB schema, auth or workflow logic are modified.
# Generated for ARKAVTHI_80PERCENT.

$ErrorActionPreference = 'Stop'

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $enc = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Text, $enc)
}

function Write-Base64File([string]$Path, [string]$Base64) {
    $parent = Split-Path -Parent $Path
    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
    }
    $clean = $Base64 -replace '\s',''
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($clean))
}

$Root = (Get-Location).Path
$Required = Join-Path $Root 'frontend\src\components\ProjectDashboard.tsx'
if (-not (Test-Path -LiteralPath $Required)) {
    throw "Run this patch from the ARKAVTHI_80PERCENT project root. Missing: $Required"
}

$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$BackupRoot = Join-Path $Root ("patch_backups\overview_introduction_" + $Stamp)
New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

$Targets = @(
    'frontend\src\components\ProjectDashboard.tsx',
    'frontend\src\components\IntroductionSection.tsx',
    'frontend\src\components\RiverOverviewFacts.tsx',
    'frontend\src\components\StudyAreaMapPreview.tsx',
    'frontend\src\data\projectOverview.ts',
    'frontend\public\project\arkavathi-study-area-map.png'
)

$CreatedByPatch = New-Object System.Collections.Generic.List[string]
foreach ($rel in $Targets) {
    $src = Join-Path $Root $rel
    if (Test-Path -LiteralPath $src) {
        $dst = Join-Path $BackupRoot $rel
        $parent = Split-Path -Parent $dst
        New-Item -ItemType Directory -Path $parent -Force | Out-Null
        Copy-Item -LiteralPath $src -Destination $dst -Force
    } else {
        $CreatedByPatch.Add($rel)
    }
}

