nSkqhzCPKjkAAAAASUVORK5CYII=
'@

    # 6) Surgically patch ProjectDashboard.tsx. Do not overwrite unrelated dashboard logic.
    $dashboardPath = Join-Path $Root 'frontend\src\components\ProjectDashboard.tsx'
    $dashboard = Get-Content -Raw -LiteralPath $dashboardPath

    if ($dashboard -notmatch "StudyAreaMapPreview") {
        $oldLucide = "import { Activity, ArrowLeft, Clock3, MapPinned, Mountain, PersonStanding, Plane, Route, Rows3 } from 'lucide-react'"
        if (-not $dashboard.Contains($oldLucide)) {
            throw 'ProjectDashboard.tsx import layout differs from the supplied project. No dashboard changes were applied.'
        }
        $dashboard = $dashboard.Replace($oldLucide, "import { ArrowLeft, PersonStanding } from 'lucide-react'")
        $dashboard = [regex]::Replace($dashboard, "(?m)^import \{ KpiCard \} from '\./KpiCard'\r?\n", '')

        $videoImport = "import { ArkavathiVideoShowcase } from './ArkavathiVideoShowcase'"
        if (-not $dashboard.Contains($videoImport)) {
            throw 'Could not locate ArkavathiVideoShowcase import in ProjectDashboard.tsx.'
        }
        $dashboard = $dashboard.Replace(
            $videoImport,
            $videoImport + "`r`nimport { StudyAreaMapPreview } from './StudyAreaMapPreview'`r`nimport { RiverOverviewFacts } from './RiverOverviewFacts'"
        )

       $overviewPattern = "(?m)^  \{activePage==='overview'&&<div className=`"space-y-5`">.*$"
        if (-not [regex]::IsMatch($dashboard, $overviewPattern)) {
            throw 'Could not locate the existing Overview render block in ProjectDashboard.tsx.'
        }

        $newOverview = @'
  {activePage==='overview'&&<div className="space-y-5"><div className="grid gap-4 lg:grid-cols-[minmax(0,7fr)_minmax(300px,3fr)]"><ArkavathiVideoShowcase/><StudyAreaMapPreview/></div><section className="rounded-2xl border border-blue-100 bg-blue-50/70 px-4 py-3 text-xs leading-5 text-navy-900"><strong>{user.organization_type==='CNNL'?'CNNL monitoring access':'Nakshatech controlled access'}:</strong> V1.8 permissions are enforced by the backend. Task review, technical approval, final approval and integration are separate auditable actions.</section><RiverOverviewFacts/><IntroductionSection/><ProjectEventsShowcase/><section className="rounded-2xl bg-navy-950 p-5 text-white"><h3 className="font-black">Current authenticated build · V1.9.3 / V29.4</h3><p className="mt-2 max-w-5xl text-sm leading-6 text-blue-100">Department uploads remain passkey-protected. Institution data stays isolated. Nakshatech controls technical review, final approval and central integration. CNNL receives only final-approved/integrated workflow outputs.</p></section></div>}
'@
        $dashboard = [regex]::Replace($dashboard, $overviewPattern, $newOverview, 1)
        Write-Utf8NoBom $dashboardPath $dashboard
    } else {
        Write-Host 'ProjectDashboard.tsx already contains this Overview integration; skipping duplicate patch.' -ForegroundColor Yellow
    }

    # 7) TypeScript validation when the local TypeScript compiler and node are available.
    $tsc = Join-Path $Root 'frontend\node_modules\typescript\bin\tsc'
    $node = Get-Command node -ErrorAction SilentlyContinue
    if ($node -and (Test-Path -LiteralPath $tsc)) {
        Write-Host 'Running TypeScript validation...' -ForegroundColor Cyan
        & $node.Source $tsc --noEmit -p (Join-Path $Root 'frontend\tsconfig.json')
        if ($LASTEXITCODE -ne 0) {
            throw "TypeScript validation failed with exit code $LASTEXITCODE."
        }
    } else {
        Write-Host 'TypeScript validation skipped because node or frontend TypeScript is not available in this terminal.' -ForegroundColor Yellow
    }

    Write-Host ''
    Write-Host 'PATCH APPLIED SUCCESSFULLY' -ForegroundColor Green
    Write-Host 'Frontend-only changes:' -ForegroundColor Cyan
    Write-Host '  - Video remains functional and now uses ~70% width on large screens.'
    Write-Host '  - Client-supplied Arkavathi study-area map occupies ~30% beside the video.'
    Write-Host '  - Old flight KPI row is replaced by horizontal river/project fact cards.'
    Write-Host '  - About Us now contains Understanding the Pollution, From Data to Action and Key Focus Areas.'
    Write-Host '  - NGO is renamed to Collaboration with NGO + institute presentation.'
    Write-Host '  - Study Area Map section is added with Arkavathi + 3 tributary explanations.'
    Write-Host '  - No backend files were changed.'
    Write-Host ''
    Write-Host ("Backup created at: " + $BackupRoot) -ForegroundColor DarkGray
    Write-Host 'If Vite is already running, use Ctrl+Shift+R in the browser.' -ForegroundColor Cyan
    Write-Host 'Otherwise: cd .\frontend ; npm.cmd run dev' -ForegroundColor Cyan
}
catch {
    Write-Host ''
    Write-Host ('Patch failed: ' + $_.Exception.Message) -ForegroundColor Red
    Write-Host 'Restoring files from the automatic backup...' -ForegroundColor Yellow

    foreach ($rel in $Targets) {
        $backup = Join-Path $BackupRoot $rel
        $dest = Join-Path $Root $rel
        if (Test-Path -LiteralPath $backup) {
            $parent = Split-Path -Parent $dest
            New-Item -ItemType Directory -Path $parent -Force | Out-Null
            Copy-Item -LiteralPath $backup -Destination $dest -Force
        } elseif ($CreatedByPatch.Contains($rel) -and (Test-Path -LiteralPath $dest)) {
            Remove-Item -LiteralPath $dest -Force
        }
    }

    Write-Host 'Rollback complete. Your pre-patch frontend files have been restored.' -ForegroundColor Green
    throw
}
